AppProto AppLayerProtoDetectDetect(
    AppLayerProtoDetectThreadCtx *tctx, Flow *f, uint8_t *buf, uint32_t buflen,
    uint8_t ipproto, uint8_t direction)
{
    AppProto proto = ALPROTO_UNKNOWN;

    if (!FlowGetFlag(f, FLOW_PROTO_DETECT_DONE)) {
        /* Attempt to detect using passive monitoring (PM) methods */
        proto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (proto != ALPROTO_UNKNOWN)
            return proto;

        /* Check other applicable detection methods */
        proto = AppLayerProtoDetectOther(tctx, f, buf, buflen, ipproto, direction);
        if (proto != ALPROTO_UNKNOWN)
            return proto;
    }

    /* If PM is complete, check using post-processing (PP) methods */
    proto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
    if (proto != ALPROTO_UNKNOWN)
        return proto;

    /* Check against expectation list if protocol is still unknown */
    proto = AppLayerProtoDetectExpectation(f, ipproto, direction);
    if (proto != ALPROTO_UNKNOWN)
        return proto;

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx,
                                   Flow *f,
                                   uint8_t *buf,
                                   uint32_t buflen,
                                   uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f)) {
        if (!FlowGetAppProtoPM(f)) {
            alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
            if (alproto != ALPROTO_UNKNOWN) {
                goto end;
            }
        }

        alproto = AppLayerProtoDetectPP(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            goto end;
        }

        alproto = AppLayerProtoDetectExpectation(f, ipproto);
        if (alproto != ALPROTO_UNKNOWN) {
            goto end;
        }
    } else {
        alproto = FlowGetAppProto(f);
    }

end:
    return alproto;
}

AppProto DetectAppLayerProtocol(AppLayerProtoDetectThreadCtx *tctx, Flow *f, uint8_t *buf,
                                uint32_t buflen, uint8_t ipproto, uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f, direction)) {
        /* Attempt passive protocol detection */
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto, direction);
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        /* Attempt post-processing protocol detection if PM is complete */
        if (FlowPMCompleted(f, direction)) {
            alproto = AppLayerProtoDetectPP(tctx, f, ipproto, direction);
            if (alproto != ALPROTO_UNKNOWN) {
                FlowSetAppProto(f, alproto, direction);
            }
        }
    }

    if (alproto == ALPROTO_UNKNOWN) {
        /* Check against expectation list */
        alproto = AppLayerProtoDetectExpectationList(f, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN) {
            FlowSetAppProto(f, alproto, direction);
        }
    }

    return FlowGetAppProto(f, direction);
}

AppProto DetectAppLayerProtocol(AppLayerProtoDetectThreadCtx *tctx, Flow *f, uint8_t *buf, uint32_t buflen, uint8_t ipproto, uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetFlag(f, FLOW_FLAG_PM_DONE)) {
        alproto = AppLayerProtoDetectPM(tctx, f, buf, buflen, ipproto, direction);
        if (alproto != ALPROTO_UNKNOWN)
            return alproto;

        FlowSetFlag(f, FLOW_FLAG_PM_DONE);
    }

    alproto = AppLayerProtoDetectPP(tctx, f, ipproto, direction);
    if (alproto != ALPROTO_UNKNOWN)
        return alproto;

    alproto = AppLayerProtoDetectExpectation(f, ipproto);
    if (alproto != ALPROTO_UNKNOWN)
        return alproto;

    return ALPROTO_UNKNOWN;
}

AppProto AppLayerProtoDetectDetect(AppLayerProtoDetectThreadCtx *tctx, Flow *f,
                                   uint8_t *buf, uint32_t buflen, uint8_t ipproto,
                                   uint8_t direction) {
    AppProto alproto = ALPROTO_UNKNOWN;

    if (!FlowGetAppProto(f)) {
        if (!FlowIsPmCompleted(f)) {
            alproto = AppLayerProtoDetectDetectPM(tctx, f, buf, buflen, ipproto, direction);
        }

        if (alproto == ALPROTO_UNKNOWN) {
            alproto = AppLayerProtoDetectDetectPP(tctx, f, buf, buflen, ipproto, direction);
        }

        if (alproto == ALPROTO_UNKNOWN) {
            alproto = AppLayerProtoDetectDetectExpectation(f, ipproto);
        }
    } else {
        alproto = FlowGetAppProto(f);
    }

    return alproto;
}
